input.sparql:
SELECT ?point_id ?power_series WHERE {
  ?point_id rdf:type brick:Electric_Power_Sensor ;
            brick:hasQuantityKind bldg:Power ;
            ref:hasTimeseriesId ?power_series .
  ?point_id brick:isPointOf [rdf:type brick:Lighting ; brick:isContainedIn ?zone] .
  ?zone rdf:type brick:Perimeter_mid_ZN_3 .
  OPTIONAL { ?zone brick:hasPoint ?occupancy_point .
             ?occupancy_point rdf:type brick:Occupancy_Sensor ;
                              ref:hasTimeseriesId ?occupancy_series . }
}
